import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
            if p_val < 0.05:
                sig_features.append((fid, t_stat))

    # Sort by absolute t-statistic
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for correlated pairs with |r| >= 0.6
    correlations = {}
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(feats.ids[i], feats.ids[j])] = corr

    # Look for product terms among top features
    top_features = [fid for fid, _ in sig_features[:10]]
    candidates = []

    # Try all pairs of top features to form products
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            a, b = top_features[i], top_features[j]
            # Check if they're not highly correlated
            if not any((a == x and b == y) or (a == y and b == x) 
                      for x, y in correlations.keys()):
                candidates.append((a, b))

    # Try product terms with highest correlation
    best_pair = None
    best_p = 1.0
    for a, b in candidates:
        col_a = feats.column(a)
        col_b = feats.column(b)
        prod = feats.x[:, col_a] * feats.x[:, col_b]
        t_stat = prod.T @ feats.y / np.sqrt(np.var(prod) * np.mean(feats.y) * (1 - np.mean(feats.y)))
        p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
        if p_val < best_p:
            best_p = p_val
            best_pair = (a, b)

    # If we found a significant product term, return it
    if best_pair and best_p < 0.05:
        a, b = best_pair
        return Design(
            drivers=(a, b),
            columns=(a, b),
            products=((a, b),),
            loadings={a: 1.0, b: 1.0}
        )

    # Otherwise return empty design
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

